import { readFile } from "node:fs/promises"
import { Effect } from "effect"

export interface FeedSnapshot {
  readonly source: string
  readonly content: string
}

const retryRead = <A, E, R>(
  task: Effect.Effect<A, E, R>,
  retries: number
): Effect.Effect<A, E, R> =>
  Effect.catchAll(task, (error) =>
    retries > 0
      ? retryRead(task, retries - 1)
      : Effect.fail(error)
  )

export const loadFeedSnapshot = (
  path: string
): Effect.Effect<FeedSnapshot, Error> => {
  const read = Effect.tryPromise({
    try: () => readFile(path, "utf8"),
    catch: (cause) => new Error(`Cannot read feed snapshot: ${path}`, { cause })
  })

  return retryRead(read, 2).pipe(
    Effect.map((content) => ({ source: path, content })),
    Effect.tap((snapshot) =>
      Effect.logDebug("Loaded feed snapshot", {
        source: snapshot.source,
        characters: snapshot.content.length
      })
    )
  )
}

